window.products.push({"id":1067592,"name":"Piazza Pisano Hummingbird Custom Home Sign","category":"homeandappliances","retail price":89.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/71Ylf2-9ipL._AC_SL1200_.jpg","description":"Our Hummingbird Personalized Sign is created from an original wood carving by artist Al Pisano and has an area in the middle to carve your name or address. We can carve 1 or 2 lines about 15 characters per line. We hand cast and then hand paint and stain each Hummingbird sign to capture all the detail of my original wood carving. We seal the sign with clear lacquer so you can hang this safely outdoors or indoors. The Hummingbird sign measures 15 inches wide and 7 inches high. We put a recessed hanger in the back for convenient hanging. Indoor or outdoor use. Made in USA.","images":["https://m.media-amazon.com/images/I/71Ylf2-9ipL._AC_SL1200_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Piazza Pisano","source_asin":"B01IRM7V4A","category_path":"Home & Kitchen"},"sku":"BM-1067592","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01IRM7V4A","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01IRM7V4A","price_pending":true,"merchant_ready":false});
